import threading


class Queue:
    """Thread-safe in-memory job queue with lease fencing."""

    def __init__(self):
        self._lock = threading.Lock()
        self._next_token = 0
        self._jobs = {}

    def _next_token(self):
        self._next_token += 1
        return self._next_token

    def add(self, job_id):
        with self._lock:
            if job_id in self._jobs:
                return
            self._jobs[job_id] = {'state': 'queued', 'worker': None, 'token': None, 'expiry': None}

    def claim(self, worker, now, ttl):
        if ttl <= 0:
            return None
        with self._lock:
            token = self._next_token()
            for job_id, job in self._jobs.items():
                if job['state'] == 'queued' or job['expiry'] <= now:
                    job['worker'] = worker
                    job['token'] = token
                    job['expiry'] = now + ttl
                    job['state'] = 'running'
                    return {'job_id': job_id, 'worker': worker, 'token': token}
            return None

    def renew(self, lease, now, ttl):
        if ttl <= 0:
            return False
        if not isinstance(lease, dict) or 'job_id' not in lease or 'token' not in lease:
            return False
        with self._lock:
            job = self._jobs.get(lease['job_id'])
            if job is None:
                return False
            if job['token'] != lease['token'] or job['worker'] != lease['worker']:
                return False
            if job['expiry'] <= now:
                return False
            job['expiry'] = now + ttl
            return True

    def complete(self, lease, now):
        if not isinstance(lease, dict) or 'job_id' not in lease or 'token' not in lease:
